function OverseaManageCookingMenuPopupDialog:RefreshUI(params,delegate)
    self.params = params
    local goodsId = self.params.data.goodsId
    local vo =  GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if vo then
        CfUtils.FillText(self.TextName,vo.name)
        CfUtils.FillImage(self.ImgIcon.gameObject,vo.photoPath)
        CfUtils.FillText(self.TextDesc,vo.desc)
        -- 设置子标题
        local goodsType = GoodsUtils.GetIdType(goodsId)
        local title = self:GetUnlockGoodsSubTitle(goodsType)
        CfUtils.FillText(self.TextTitle, title)
    end
end

--- 获取解锁新道具时子标题的文字
---@param goodsType any
function OverseaManageCookingMenuPopupDialog:GetUnlockGoodsSubTitle(goodsType)
    local title
    if goodsType == Constants.IDType.RestaurantRecipeGoods then
        title = localize("食谱料理")
    elseif goodsType == Constants.IDType.GoodsCD then
        title = localize("心音纪念")
    else
        title = localize("道具")
    end
    return title
end

function OverseaManageCookingMenuPopupDialog:CheckAnimatorPlayComplete()
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(1))
end

return OverseaManageCookingMenuPopupDialog